mapper.sql:
WHERE 1 = 1
 AND username LIKE CONCAT('%', #{username}, '%') 
 AND module = #{module} 
 AND oper_time >= #{from} 
 AND oper_time <= #{to}

mapper.select:
SELECT id, user_id AS userId, username, login_type AS loginType, result,
       fail_reason AS failReason, ip, login_time AS loginTime
FROM sys_login_log
WHERE 1 = 1
 AND username LIKE CONCAT('%', #{username}, '%') 
 AND login_time >= #{from} 
 AND login_time <= #{to} 
ORDER BY id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM sys_login_log
WHERE 1 = 1
 AND username LIKE CONCAT('%', #{username}, '%') 
 AND login_time >= #{from} 
 AND login_time <= #{to}
